                options = listOf("کاشی‌های آبی و فیروزه‌ای صاف روی دیوار مسجد", "گل‌های سفید گچی که از سقف بیرون زده‌اند", "آجرهایی که با نقش چیده شده‌اند", "یک دیوار ساده بدون هیچ نقشی"),
                correctIndex = 1,
                explanation = "گچ‌بری سفید و برجسته است و از دیوار یا سقف بیرون زده است؛ کاشی‌کاری رنگی و صاف است، آجرچینی با آجر است، و دیوار ساده تزیین ندارد."
            )
        )
    )
}
